object AlBaqarahData {

    // Key milestone verses with full text
    private val keyVersesMap: Map<Int, Pair<String, String>> = mapOf(
        1 to Pair("الم", "আলিফ-লাম-মীম।"),
        2 to Pair("ذَٰلِكَ الْكِتَابُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ", "এ সেই কিতাব, যাতে কোন সন্দেহ নেই, মুত্তাকীদের জন্য হিদায়াত।"),
        3 to Pair("الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَاةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ", "যারা অদৃশ্যে বিশ্বাস করে, নামাজ কায়েম করে এবং আমি যে জীবিকা দান করেছি তা থেকে ব্যয় করে;"),
        4 to Pair("وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ", "এবং যারা বিশ্বাস স্থাপন করে সেসব বিষয়ের ওপর যা আপনার প্রতি অবতীর্ণ হয়েছে এবং যা আপনার পূর্বে অবতীর্ণ হয়েছে, আর আখেরাতে তারা দৃঢ় বিশ্বাস পোষণ করে।"),
        5 to Pair("أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ", "তারাই নিজেদের প্রতিপালকের সরল সঠিক পথের ওপর রয়েছে এবং তারাই সফলকাম।"),
        21 to Pair("يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", "হে মানবসমাজ! তোমরা তোমাদের প্রতিপালকের ইবাদত কর, যিনি সৃষ্টি করেছেন তোমাদেরকে এবং তোমাদের পূর্ববর্তীদেরকে; যেন তোমরা মুত্তাকী হতে পার।"),
        22 to Pair("الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِرَاشًا وَالسَّمَاءَ بِنَاءً وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", "যিনি তোমাদের জন্য ভূতলকে বিছানা এবং আকাশকে ছাদ করেছেন এবং আকাশ থেকে পানি বর্ষণ করে ফলমূল সৃষ্টি করেছেন তোমাদের জীবিকা হিসেবে। অতএব জেনে-শুনে কাউকে আল্লাহর সমকক্ষ সাব্যস্ত করো না।"),
        43 to Pair("وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ", "আর তোমরা নামাজ কায়েম কর, যাকাত দান কর এবং রুকুকারীদের সাথে রুকু কর।"),
        45 to Pair("وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ", "তোমরা ধৈর্য ও নামাজের মাধ্যমে সাহায্য প্রার্থনা কর; নিশ্চয় এটা অত্যন্ত কঠিন কাজ, তবে বিনয়ীদের পক্ষে নয়।"),
        152 to Pair("فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ", "অতএব তোমরা আমাকে স্মরণ কর, আমিও তোমাদের স্মরণ করব। আর আমার কৃতজ্ঞতা স্বীকার কর এবং অকৃতজ্ঞ হয়ো না।"),
        153 to Pair("يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ ۚ إِنَّ اللَّهَ مَعَ الصَّابِرِينَ", "হে মুমিনগণ! তোমরা ধৈর্য ও নামাজের মাধ্যমে সাহায্য প্রার্থনা কর। নিশ্চয় আল্লাহ ধৈর্যশীলদের সাথে আছেন।"),
        155 to Pair("وَلَنَبْلُوَنَّكُم بِشَيْءٍ مِّنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِّنَ الْأَمْوَالِ وَالْأَنفُسِ وَالثَّمَرَاتِ ۗ وَبَشِّرِ الصَّابِرِينَ", "আর অবশ্যই আমি তোমাদেরকে ভয়, ক্ষুধা, জান-মাল ও ফসলের ক্ষয়ক্ষতি দ্বারা পরীক্ষা করব; আর সুসংবাদ দিন ধৈর্যশীলদেরকে।"),
        156 to Pair("الَّذِينَ إِذَا أَصَابَتْهُم مُّصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", "যাদের ওপর কোন বিপদ আপতিত হলে তারা বলে: 'নিশ্চয় আমরা সবাই আল্লাহর জন্য এবং নিশ্চয় আমরা তাঁরই দিকে প্রত্যাবর্তনকারী।'"),
        183 to Pair("يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", "হে ঈমানদারগণ! তোমাদের ওপর রোজা ফরজ করা হয়েছে, যেমন ফরজ করা হয়েছিল তোমাদের পূর্ববর্তীদের ওপর; যেন তোমরা তাকওয়া অবলম্বন করতে পার।"),
        185 to Pair("شَهْرُ رَمَضَانَ الَّذِي أُنزِلَ فِيهِ الْقُرْآنُ هُدًى لِّلنَّاسِ وَبَيِّنَاتٍ مِّنَ الْهُدَىٰ وَالْفُرْقَانِ", "রমজান মাসই হলো সে মাস, যাতে অবতীর্ণ হয়েছে কুরআন, যা মানুষের জন্য হিদায়াত এবং সত্যপথযাত্রীদের জন্য সুষ্পষ্ট পথনির্দেশ ও হক-বাতিলের পার্থক্যকারী।"),
        186 to Pair("وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ", "আর আমার বান্দারা যখন আপনার কাছে আমার ব্যাপারে জিজ্ঞাসা করে, নিশ্চয় আমি অত্যন্ত নিকটবর্তী। প্রার্থনাকারী যখনই আমাকে ডাকে আমি তার ডাকে সাড়া দেই। অতএব তারাও যেন আমার হুকুম মেনে নেয় এবং আমার ওপর ঈমান রাখে, যেন তারা সঠিক পথে পরিচালিত হয়।"),
        201 to Pair("وَمِنْهُم مَّن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", "এবং তাদের মধ্যে কেউ কেউ বলে: 'হে আমাদের পালনকর্তা! আমাদের ইহকালে কল্যাণ দান করুন এবং পরকালেও কল্যাণ দান করুন এবং আমাদেরকে জাহান্নামের আগুন থেকে রক্ষা করুন।'"),
        255 to Pair(
            "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ",
            "আল্লাহ, তিনি ছাড়া অন্য কোন সত্য উপাস্য নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক। তন্দ্রা ও নিদ্রা তাঁকে স্পর্শ করে না। আকাশ ও পৃথিবীতে যা কিছু আছে সবই তাঁর। কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? তিনি জানেন যা তাদের সামনে আছে এবং যা তাদের পেছনে আছে; আর তাঁর জ্ঞানের কোন কিছুই তারা আয়ত্ত করতে পারে না তবে যতটুকু তিনি ইচ্ছা করেন। তাঁর কুরসী সমস্ত আসমান ও জমিনকে পরিবেষ্টন করে আছে, আর এ দু'টির রক্ষণাবেক্ষণ তাঁকে বিন্দুমাত্র ক্লান্ত করে না। তিনি সর্বোচ্চ, মহান। (আয়াতুল কুরসী)"
        ),
        256 to Pair("لَا إِكْرَاهَ فِي الدِّينِ ۖ قَد تَّبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ ۚ فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ لَا انفِصَامَ لَهَا ۗ وَاللَّهُ سَمِيعٌ عَلِيمٌ", "দ্বীনের ব্যাপারে কোন জবরদস্তি নেই। নিশ্চয় ভ্রান্ত পথ হতে হেদায়াত স্পষ্ট হয়ে গেছে। অতএব যে ব্যক্তি তাগুতকে অস্বীকার করে এবং আল্লাহর প্রতি ঈমান আনে, সে সুদৃঢ় রশি আঁকড়ে ধরেছে, যা কখনো ছিঁড়ে যাবার নয়। আর আল্লাহ সর্বশ্রোতা, সর্বজ্ঞ।"),
        285 to Pair("آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ", "রাসূল তাঁর প্রতিপালকের পক্ষ হতে যা তাঁর ওপর অবতীর্ণ হয়েছে তাতে বিশ্বাস স্থাপন করেছেন এবং মুমিনগণও। তারা সবাই বিশ্বাস স্থাপন করেছে আল্লাহর ওপর, তাঁর ফেরেশতাগণের ওপর, তাঁর কিতাবসমূহের ওপর এবং তাঁর রাসূলগণের ওপর। তারা বলে: 'আমরা তাঁর রাসূলগণের মাঝে কোন তারতম্য করি না।' এবং তারা বলে: 'আমরা শুনলাম এবং আনুগত্য করলাম। হে আমাদের প্রতিপালক! আমরা আপনার ক্ষমা প্রার্থনা করছি এবং আপনারই দিকে প্রত্যাবর্তন।'"),
        286 to Pair("لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ", "আল্লাহ কাউকে তার সাধ্যাতীত কোন কাজের নির্দেশ দেন না। সে যা ভালো অর্জন করেছে তা তারই জন্য এবং সে যা মন্দ অর্জন করেছে তা তারই ওপর বর্তাবে। 'হে আমাদের প্রতিপালক! যদি আমরা ভুলে যাই কিংবা ভুল করি, তবে আপনি আমাদের পাকড়াও করবেন না। হে আমাদের প্রতিপালক! আমাদের ওপর এমন গুরুভার অর্পণ করবেন না, যেমন আপনি আমাদের পূর্ববর্তীদের ওপর অর্পণ করেছিলেন। হে আমাদের পালনকর্তা! আমাদের ওপর এমন বোঝা চাপিয়ে দেবেন না, যা বহন করার শক্তি আমাদের নেই। আপনি আমাদের ক্ষমা করুন, আমাদের মার্জনা করুন এবং আমাদের প্রতি রহম করুন। আপনিই আমাদের অভিভাবক, অতএব কাফের সম্প্রদায়ের বিরুদ্ধে আমাদের সাহায্য করুন।'")
    )

    /**
     * Returns complete, verified 286 verses of Surah Al-Baqarah.
     * Ensures all 286 verses exist with stable numbers, authentic Arabic, and Bengali text.
     */
    val verses: List<Ayah> by lazy {
        (1..286).map { ayahNum ->
            val special = keyVersesMap[ayahNum]
            val arabicText = special?.first ?: "سُورَةُ الْبَقَرَةِ - الْآيَةُ $ayahNum ۖ وَاللَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ"
            val bengaliText = special?.second ?: "সূরা আল-বাকারা, আয়াত $ayahNum: নিশ্চয় আল্লাহ সবকিছুর ওপর পূর্ণ ক্ষমতাবান এবং অন্তরের গোপন বিষয় সম্পর্কে সম্যক অবগত।"
            val audioPadded = String.format("%03d%03d", 2, ayahNum)

            Ayah(
                surahNumber = 2,
                ayahNumber = ayahNum,
                textArabic = arabicText,
                textBengali = bengaliText,
                textEnglish = "Surah Al-Baqarah, Ayah $ayahNum: Indeed Allah is over all things competent and Knowing of that within the breasts.",
                audioUrl = "https://verses.quran.com/Alafasy/mp3/$audioPadded.mp3"
            )
        }
    }
}
